    samples = []
    with open(cfg["jailbreak_path"]) as f:
        for line in f:
            conv = json.loads(line.strip())
            label = 1 if conv["label"] == "jailbreak" else 0
            samples.append({
                "conversation_id": conv["conversation_id"],
